'use strict';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const code=r=>'R-CONF-'+String(r.id).padStart(2,'0');
const score=r=>r.probability*r.impact;
const residual=r=>r.residual_probability*r.residual_impact;
const level=n=>n>=17?['Crítico','critical']:n>=10?['Alto','high']:n>=5?['Medio','medium']:['Bajo','low'];
const badge=n=>`<span class="badge ${level(n)[1]}">${n} · ${level(n)[0]}</span>`;
const STORE_KEY='rconf-demo-v1';
let mode='demo',role=null,token='',risks=[],events=[],filter='',statusFilter='',controlFilter='',controlKindFilter='',controlRiskFilter='',loadError='',checkResults=null,checkError='';
let activePage='overview',projectData=null;
const labels={audit:'Auditoría antes/después',database:'Oracle y scripts',overview:'Vista general',case:'Caso de estudio',risks:'Registro de riesgos',phva:'Ciclo PHVA',controls:'Controles ISO',privileges:'Mínimo privilegio',comparison:'2013 vs. 2022',evidence:'Expediente de evidencias',resources:'Documentación'};
const isDemo=()=>mode==='demo';
const canWrite=()=>isDemo()||['analista','gestor'].includes(role);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+token,...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo completar la solicitud.');return data}
function loadDemo(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));if(saved&&Array.isArray(saved.risks)&&Array.isArray(saved.events)){risks=saved.risks;events=saved.events;return}}catch{}risks=structuredClone(SEED);events=[]}
function saveDemo(){try{localStorage.setItem(STORE_KEY,JSON.stringify({risks,events}));}catch{toast('El navegador no permite guardar. Exportá el registro antes de cerrar.')}}
async function refresh(){clearDatabaseObservation();loadError='';checkResults=null;checkError='';caseDbTasks=null;caseDbTasksError='';maturityState.loadError='';if(isDemo())loadDemo();else if(token){try{[risks,events]=await Promise.all([api('/api/risks'),api('/api/events')])}catch(e){loadError=e.message;risks=[];events=[]}try{[caseDbTasks,projectData]=await Promise.all([api('/api/dba-tasks'),api('/api/project')]);const c=projectData.catalog;CONTROLS=c.controls;CONTROL_VERIFICATION=c.verification;AUDIT_TESTS=c.tests;REQUIRED_CONTROL_MATRIX=c.matrix;DBA_TASKS=caseDbTasks.map(t=>({task:t.task,action:t.action,risk:risks.filter(r=>selectedControls(r).some(c=>(t.controls.match(/\d+\.\d+/g)||[]).includes(c.id))).map(code).join(' · ')||'Sin vínculo',controls:t.controls,evidence:t.evidence}));if(!maturityState.dirty){maturityState.rows=cleanMaturityImport(projectData.maturity.rows,new Set(CONTROLS.map(x=>x.id)));maturityState.target=projectData.maturity.target;maturityState.version=projectData.version}else{maturityState.version=null;maturityState.loadError='Hay una matriz local sin guardar. Exportala y recargá antes de cargar la de Oracle.'}}catch(e){caseDbTasksError=e.message;maturityState.loadError='No se pudo cargar el expediente de Oracle: '+e.message}try{if(!caseLocalState.data){const actual=await api('/api/case-local');caseLocalState.data=actual;const pair=auditPair('case');if(!pair.before&&!pair.after&&actual.captures?.before&&actual.captures?.after){const b=parseCaseCapture(actual.captures.before.content,'BEFORE'),a=parseCaseCapture(actual.captures.after.content,'AFTER');if(compareCaseCaptures(b,a).comparable)(auditState.files.case={before:actual.captures.before,after:actual.captures.after},caseLocalState.auditRef=auditState.files.case)}}}catch(e){caseLocalState.error=e.message}}else{risks=[];events=[];maturityState.version=null;caseLocalState.data=null;if(auditState.files.case===caseLocalState.auditRef)delete auditState.files.case;caseLocalState.auditRef=null}render()}
function title(heading,description,action=''){return `<div class="page-title"><div><h1>${heading}</h1><p>${description}</p></div>${action}</div>`}
function caseBrief(){return `<section class="engagement-brief" aria-label="Alcance del caso"><div><span class="brief-kicker">Caso de estudio · organización ficticia</span><h2>Faro Servicios S.A.</h2><p>Revisión de exposición de datos en Oracle 21c XE, PDB XEPDB1. El escenario inicial es hipotético; los resultados de Oracle proceden de salidas compartidas por el estudiante.</p><a class="brief-link" href="#case">Abrir expediente del caso</a></div><div class="brief-facts"><div><strong>02</strong><span>pruebas conformes según salida aportada</span></div><div><strong>01</strong><span>hallazgo de auditoría por aclarar</span></div><small>Alcance académico · sin certificación</small></div></section>`}
function modeNotice(){const brief=activePage==='overview'?caseBrief():'';if(isDemo())return brief+'<div class="notice"><strong>Demostración con datos sintéticos.</strong> Los cambios se guardan en este navegador. Los riesgos residuales son estimaciones y las evidencias DEM son ilustrativas; no prueban controles ejecutados en Oracle.</div>';return brief+`<div class="notice"><strong>Modo Oracle ${role?'· '+esc(role):'· sesión requerida'}.</strong> ${loadError?esc(loadError):'Las evidencias se registran como referencias. No cargués secretos ni datos personales.'}</div>`}
function riskRows(rows,brief=false){if(!rows.length)return `<tr><td colspan="8" class="empty">${!isDemo()&&!token?'Conectá una sesión para consultar los riesgos.':'No hay riesgos para los filtros seleccionados.'}</td></tr>`;return rows.map(r=>`<tr><td><span class="risk-code">${code(r)}</span></td><td><button class="inline-button" data-edit="${r.id}">${esc(r.title)}</button><small>${esc(r.asset)}</small></td><td>${badge(score(r))}</td>${brief?'':`<td>${badge(residual(r))}<small>Estimado</small></td>`}<td><span class="badge">${esc(r.phase)}</span></td><td>${esc(r.owner)}</td>${brief?'':`<td>${esc(r.status)}<small>${esc(r.due)}</small></td>`}<td><button class="quiet" data-edit="${r.id}">${canWrite()?'Editar':'Ver'}</button></td></tr>`).join('')}
function riskTable(rows,brief=false){return `<div class="table-scroll"><table><thead><tr><th>Identificador</th><th>Riesgo y activo</th><th>Inherente</th>${brief?'':'<th>Residual</th>'}<th>Fase PHVA</th><th>Responsable</th>${brief?'':'<th>Estado / objetivo</th>'}<th></th></tr></thead><tbody>${riskRows(rows,brief)}</tbody></table></div>`}
function riskMatrix(residualMode=false){const pk=residualMode?'residual_probability':'probability',ik=residualMode?'residual_impact':'impact';let cells='';for(let p=5;p>=1;p--){cells+=`<span class="matrix-axis">P${p}</span>`;for(let i=1;i<=5;i++){const found=risks.filter(r=>r[pk]===p&&r[ik]===i),cls=level(p*i)[1];cells+=`<div class="matrix-square heat-${cls==='medium'?'mid':cls}" aria-label="Probabilidad ${p}, impacto ${i}, ${found.length} riesgos">${found.map(r=>`<button type="button" class="matrix-risk" data-edit="${esc(r.id)}" title="${esc(code(r)+': '+r.title)}" aria-label="${esc(code(r)+': '+r.title)}">${esc('R'+String(r.id).padStart(2,'0'))}</button>`).join('')}</div>`}}cells+='<span></span>'+[1,2,3,4,5].map(i=>`<span class="matrix-axis">I${i}</span>`).join('');return `<div class="risk-matrix">${cells}</div>`}
function heatmap(){return `<div class="risk-matrices"><section class="matrix-card"><h3>Riesgo inherente</h3><p>Valoración inicial registrada · antes del tratamiento</p>${riskMatrix(false)}</section><section class="matrix-card"><h3>Riesgo residual estimado</h3><p>Valor previsto después del tratamiento propuesto</p>${riskMatrix(true)}</section></div><div class="legend">${[['Bajo 1–4','low'],['Medio 5–9','mid'],['Alto 10–16','high'],['Crítico 17–25','critical']].map(([l,c])=>`<span><i class="dot heat-${c}"></i>${l}</span>`).join('')}</div><p class="risk-matrix-note">Cada etiqueta identifica un riesgo; seleccioná una para verlo. El residual es una estimación registrada, no una medición posterior: requiere evidencia y revisión. La posición inicial no acredita una medición histórica anterior.</p>${risks.length?'':`<p class="risk-matrix-empty">${!isDemo()&&!token?'Conectá una sesión para ver los riesgos de Oracle.':'Todavía no hay riesgos registrados.'}</p>`}`}

function overview(){const severe=risks.filter(r=>score(r)>=10).length,withEvidence=risks.filter(r=>r.evidence).length,closed=risks.filter(r=>['Mitigado','Aceptado'].includes(r.status)).length;return title('Confidencialidad bajo control','Identificá, tratá y verificá los riesgos de tus bases de datos Oracle.',`<button class="primary" id="new-risk" ${canWrite()?'':'disabled'}>＋ Registrar riesgo</button>`)+modeNotice()+`<div class="stats"><div class="stat"><div class="label">Riesgos registrados</div><div class="number">${risks.length.toString().padStart(2,'0')}</div><small>Alcance: confidencialidad en Oracle</small></div><div class="stat"><div class="label">Riesgo inherente alto o crítico</div><div class="number red">${severe.toString().padStart(2,'0')}</div><small>Prioridad de tratamiento</small></div><div class="stat"><div class="label">Con referencia de evidencia</div><div class="number teal">${withEvidence} <small>/ ${risks.length}</small></div><small>${isDemo()?'Referencias ilustrativas':'Pendientes de revisión por auditor'}</small></div><div class="stat"><div class="label">Decisiones de riesgo residual</div><div class="number">${closed.toString().padStart(2,'0')}</div><small>Mitigado o aceptado por gestor</small></div></div><section class="panel risk-comparison-panel"><div class="panel-heading"><div><h2>Comparación de exposición</h2><small>Probabilidad × impacto · escala de 1 a 5</small></div><span class="pill">Antes y residual estimado</span></div>${heatmap()}</section><div class="grid-main risk-phva-grid"><section class="panel"><div class="panel-heading"><div><h2>Del riesgo a la mejora</h2><small>Distribución de registros en el ciclo PHVA</small></div><a href="#phva">Ver ciclo</a></div><div class="phva-list">${PHASES.map((p,i)=>{let count=risks.filter(r=>r.phase===p).length;return `<div class="phase-row"><div class="phase-letter">${['P','H','V','A'][i]}</div><div><div class="phase-label"><span>${p}</span><small>${['Evaluar y priorizar','Aplicar controles','Comprobar resultados','Aprobar y mejorar'][i]}</small></div><progress max="100" value="${risks.length?count/risks.length*100:0}" aria-label="${p}"></progress></div><span>${count} / ${risks.length}</span></div>`}).join('')}</div><div class="helper">Cada avance requiere una referencia de evidencia. El gestor documenta la decisión sobre el riesgo residual.</div></section></div><section class="panel table-panel"><div class="panel-heading"><div><h2>Riesgos prioritarios</h2><small>Ordenados por exposición inherente</small></div><a href="#risks">Ver registro completo</a></div>${riskTable([...risks].sort((a,b)=>score(b)-score(a)).slice(0,5),true)}</section>`}
function registry(){return title('Registro de riesgos','La confidencialidad se protege con decisiones trazables.',`<div class="button-row"><button id="export" class="secondary">Exportar JSON</button><button id="new-risk" class="primary" ${canWrite()?'':'disabled'}>＋ Registrar riesgo</button></div>`)+modeNotice()+`<div class="toolbar"><input id="search" aria-label="Buscar riesgos" placeholder="Buscar por riesgo, activo o responsable…" value="${esc(filter)}"><select id="status-filter" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${STATUSES.map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><section class="panel table-panel" id="registry-table">${filteredTable()}</section><p class="risk-level-note">Criterio del proyecto: 1–4 bajo, 5–9 medio, 10–16 alto, 17–25 crítico. ISO no prescribe esta fórmula. El residual se valida mediante evidencia y aprobación.</p>`}
function filteredTable(){const f=filter.toLocaleLowerCase('es');return riskTable(risks.filter(r=>(!statusFilter||r.status===statusFilter)&&[r.title,r.asset,r.owner,code(r)].some(x=>x.toLocaleLowerCase('es').includes(f))))}
function selectedControls(r){const ids=String(r.controls||'').split(',').map(x=>x.trim());return ids.map(id=>CONTROLS.find(c=>c.id===id)).filter(Boolean)}
function riskAdvice(r,controls){const lead=controls[0],priority=score(r)>=10,hasEvidence=Boolean(String(r.evidence||'').trim()),remaining=residual(r);switch(r.phase){
case 'Planificar':return {heading:priority?'Tratamiento prioritario':'Definir el tratamiento',action:`Acordá con ${r.owner||'el responsable'} el criterio de éxito para ${r.asset||'el activo'}, justificá los controles elegidos y convertí el tratamiento registrado en tareas verificables.`,proof:'Dejá trazables la decisión, el responsable, la fecha y el resultado esperado.'};
case 'Hacer':return {heading:'Aplicar el control',action:`Ejecutá el tratamiento registrado para ${r.asset||'el activo'} con una cuenta autorizada. Conservá la configuración previa, el cambio y la ruta de reversión.`,proof:`${lead?lead.evidence:'Conservá la configuración y la salida de ejecución.'} ${hasEvidence?'Revisá que la referencia actual apunte al archivo original.':'Agregá una referencia al archivo original antes de avanzar.'}`};
case 'Verificar':return {heading:'Comprobar la eficacia',action:'Compará lo esperado con lo observado. Ejecutá una prueba de acceso permitido y otra de acceso denegado cuando correspondan al control.',proof:`${lead?lead.evidence:'Conservá la salida de la prueba.'} ${hasEvidence?'Revisá la referencia existente con fecha, cuenta y entorno.':'Registrá la referencia de evidencia antes de concluir.'}`};
case 'Actuar':return {heading:remaining>4?'Resolver el residual':'Cerrar o ajustar el tratamiento',action:remaining>4?'El residual estimado supera 4: continuá el tratamiento o solicitá al gestor una aceptación justificada.':'El gestor debe revisar las pruebas, justificar la decisión y programar la próxima revisión.',proof:hasEvidence?'Validá la evidencia existente y documentá la decisión del gestor.':'Falta la referencia de evidencia para sustentar la decisión.'};
default:return {heading:'Revisar el riesgo',action:'Comprobá la fase y el tratamiento registrados.',proof:'Conservá la evidencia correspondiente.'}}}
function phvaRiskCard(r){const controls=selectedControls(r),advice=riskAdvice(r,controls),evidence=String(r.evidence||'').trim();return `<article class="risk-card"><div class="risk-card-head"><span class="risk-code">${code(r)}</span>${badge(score(r))}</div><h3>${esc(r.title)}</h3><p class="risk-card-asset">${esc(r.asset)} · ${esc(r.owner)} · ${esc(r.due)}</p><div class="risk-card-plan"><span>Tratamiento registrado</span><p>${esc(r.treatment||'Sin tratamiento definido.')}</p></div><div class="risk-card-advice"><span>Recomendación · ${esc(advice.heading)}</span><p>${esc(advice.action)}</p><small>${esc(advice.proof)}</small></div><div class="risk-card-footer"><span>Residual estimado: ${badge(residual(r))}</span><small>${evidence?'Referencia: '+esc(evidence):'Evidencia pendiente'}</small></div><details class="risk-card-details"><summary>Controles y evidencia esperada (${controls.length})</summary>${controls.length?controls.map(c=>`<div><strong>${esc(c.id)} · ${esc(c.title)}</strong><p>${esc(c.implementation)}</p><small>${esc(c.evidence)}</small></div>`).join(''):'<p>No hay controles del catálogo vinculados a este registro.</p>'}</details><button class="inline-button" data-edit="${r.id}">${canWrite()?'Revisar tratamiento':'Ver riesgo'}</button></article>`}
function localChecksPanel(){const canRun=!isDemo()&&Boolean(token)&&!loadError;return `<section class="panel local-checks section-gap" id="local-checks"><div class="panel-heading"><div><span class="section-tag">Consola de comprobación · Oracle local</span><h2>Ejecutar pruebas de acceso mínimo</h2><small>El servidor usa RCONF_APP para cuatro consultas predefinidas. No ejecuta SQL ingresado por el usuario ni instala objetos.</small></div><button class="primary" id="run-runtime-check" ${canRun?'':'disabled'}>Ejecutar comprobación</button></div>${isDemo()?'<p class="subtle">Para ejecutar las pruebas, iniciá el servidor en modo Oracle y conectá una sesión.</p>':!token?'<p class="subtle">Conectá una sesión para habilitar la comprobación local.</p>':''}${checkError?`<p class="form-error" role="alert">${esc(checkError)}</p>`:''}${checkResults?`<div class="check-result-head"><strong>${esc(checkResults.account)} · ${esc(checkResults.pdb)}</strong><span>${esc(checkResults.checked_at)}</span><button class="secondary" id="download-check">Descargar resultado JSON</button></div><div class="check-grid">${checkResults.results.map(x=>`<div class="check-result ${esc(x.status)}"><span>${esc(x.id)}</span><strong>${esc(x.title)}</strong><em>${esc(x.status)}</em><p>${esc(x.observed)}</p></div>`).join('')}</div><p class="subtle">Resultado temporal: guardá el JSON y la salida SQL*Plus original con fecha, ejecutor y revisor antes de vincular una EV. Las pruebas directas de UPDATE y el rastro DBA se hacen con los scripts indicados.</p>`:''}<details class="command-guide"><summary>Comandos SQL*Plus para completar la evidencia</summary><div class="command-grid"><div><strong>RCONF_APP · prueba completa</strong><p>Desde la carpeta del proyecto; SQL*Plus solicitará la contraseña.</p><pre>sqlplus /nolog<br>CONNECT RCONF_APP@localhost:1521/XEPDB1<br>@sql/05_verify_runtime.sql</pre></div><div><strong>SYSDBA · rastro de auditoría</strong><p>En una sesión administrativa separada. No introducir la contraseña en la página.</p><pre>sqlplus /nolog<br>CONNECT sys@localhost:1521/XEPDB1 AS SYSDBA<br>@sql/04_verify_dba.sql</pre></div></div><p class="subtle">Los scripts 01–03 son de instalación inicial y no deben repetirse para la demostración. Ejecutá 06_lock_owner.sql como DBA al cerrar la instalación, después de verificar sus efectos.</p></details></section>`}
function phva(){const visible=isDemo()||Boolean(token);return title('Un ciclo de mejora verificable','Cada riesgo muestra una próxima acción, los controles elegidos y la evidencia que falta revisar.')+modeNotice()+`<div class="notice"><strong>Orientación para decidir.</strong> Las recomendaciones se generan a partir de la fase, exposición, residual y controles seleccionados. El responsable debe validarlas; una referencia de evidencia no acredita por sí sola la eficacia.</div><div class="kanban">${PHASES.map((p,i)=>{const phaseRisks=risks.filter(r=>r.phase===p).sort((a,b)=>score(b)-score(a));return `<section class="kanban-col"><h2>${['P','H','V','A'][i]} · ${p}</h2><p>${['Identificar activos, amenazas, impacto, responsables y criterios.','Aplicar el plan de tratamiento y conservar su evidencia.','Ejecutar pruebas y contrastar el resultado con los criterios.','Aprobar el residual, corregir hallazgos y planificar otra revisión.'][i]}</p><span class="pill">${visible?phaseRisks.length+' riesgo'+(phaseRisks.length===1?'':'s'):'Sesión requerida'}</span>${phaseRisks.length?phaseRisks.map(phvaRiskCard).join(''):`<div class="kanban-empty">${visible?'Sin riesgos en esta fase.':'Conectá una sesión para ver los riesgos.'}</div>`}</section>`}).join('')}</div>${localChecksPanel()}<div class="panel section-gap"><h2>Cómo se relaciona con ISO/IEC 27001</h2><p class="copy">Se utiliza PHVA como método pedagógico: Planificar se relaciona con las cláusulas 4 a 7; Hacer con la 8; Verificar con la 9; Actuar con la 10. Esta correspondencia es una interpretación de implementación y no una certificación del SGSI.</p></div>`}
function filteredControls(){const q=controlFilter.toLocaleLowerCase('es'),risk=risks.find(r=>String(r.id)===controlRiskFilter),ids=risk?new Set(selectedControls(risk).map(c=>c.id)):null;return CONTROLS.filter(c=>(!controlKindFilter||c.kind===controlKindFilter)&&(!ids||ids.has(c.id))&&[c.id,c.title,c.kind,c.old,c.implementation,c.evidence].some(x=>x.toLocaleLowerCase('es').includes(q)))}
function controlMaturity(){const names={0:'Sin evidencia',1:'Propuesto',2:'Parcialmente implementado',3:'Implementado y probado en laboratorio',4:'Sostenido y revisado'};return `<section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>Matriz de madurez de los 15 controles requeridos</h2><small>Autoevaluación documental inicial · escala 0–4</small></div><a href="/documents/01_informe_academico.pdf" target="_blank" rel="noopener">Abrir informe PDF</a></div><div class="notice">La puntuación describe la evidencia disponible para este laboratorio, no el cumplimiento de una organización. 0 significa que no hay evidencia disponible; no prueba por sí solo la ausencia del control. “Cumple” requiere evidencia suficiente y validada. Ningún control se marca Cumple porque quedan revisiones pendientes.</div><div class="table-scroll"><table><thead><tr><th>Control</th><th>Nivel</th><th>Escala</th><th>Estado</th><th>Evidencia / brecha</th><th>Prueba</th></tr></thead><tbody>${REQUIRED_CONTROL_MATRIX.map(m=>`<tr><td><strong>${esc(m.id)}</strong> · ${esc(CONTROLS.find(c=>c.id===m.id)?.title||'')}</td><td>${m.score}/4</td><td>${esc(names[m.score])}</td><td><span class="pill">${esc(m.status)}</span></td><td>${esc(m.evidence)}</td><td>${esc(m.test)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Escala: 0 sin evidencia disponible; 1 diseño/propuesta; 2 implementación parcial; 3 implementado y probado en laboratorio; 4 sostenido con revisión periódica. La asignación académica pide una matriz observable: completá la columna de revisor/fecha cuando valides las salidas originales.</p></section>`}
function dbaTaskTable(){return `<section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>12 tareas del administrador de bases de datos</h2><small>El alcance DBA convierte riesgos de confidencialidad en operaciones concretas.</small></div></div><div class="table-scroll"><table><thead><tr><th>Tarea</th><th>Acción</th><th>Riesgo</th><th>Control</th><th>Evidencia observable</th></tr></thead><tbody>${DBA_TASKS.map(t=>`<tr><td><strong>${esc(t.task)}</strong></td><td>${esc(t.action)}</td><td>${esc(t.risk)}</td><td>${esc(t.controls)}</td><td>${esc(t.evidence)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">TDE, Data Redaction y otras funciones dependen de edición/licencia/configuración. El plan las trata como opciones a verificar, no como funciones habilitadas en XE.</p></section>`}
function controlCards(data){const known=isDemo()||Boolean(token),requiredIds=new Set(REQUIRED_CONTROL_MATRIX.map(x=>x.id));return data.length?data.map(c=>{const linked=risks.filter(r=>selectedControls(r).some(x=>x.id===c.id));return `<article class="control-card iso-control"><div class="iso-control-head"><span class="control-number">${esc(c.id)}</span><span class="control-kind">${esc(c.kind)}</span></div><div class="control-badges">${requiredIds.has(c.id)?'<span class="pill pill-required">Requerido por asignación</span>':'<span class="pill">Complementario</span>'}</div><h3>${esc(c.title)}</h3><div class="control-block"><span>Aplicación propuesta</span><p>${esc(c.implementation)}</p></div><div class="control-block evidence-block"><span>Evidencia esperada</span><p>${esc(c.evidence)}</p></div><div class="control-block"><span>Ruta de comprobación</span><p>${esc(CONTROL_VERIFICATION[c.id]||'Definir una prueba apropiada al entorno.')}</p></div><div class="control-mapping"><span>Referencia 2013</span><strong>${esc(c.old)}</strong></div><div class="control-links"><span>Riesgos vinculados en el registro</span><p>${known?(linked.length?linked.map(r=>`<button class="inline-button" data-edit="${r.id}">${code(r)}</button>`).join(''):'Aún sin riesgo vinculado.'):'Conectá una sesión para consultar.'}</p></div></article>`}).join(''):'<p class="empty">No hay controles para los filtros seleccionados.</p>'}
function auditorControlsTable(){return `<section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>15 controles observables para revisión externa</h2><small>Qué debería solicitar y comprobar un auditor según el alcance y la evidencia disponible.</small></div><a href="sql/08_auditor_controls.sql" download>Descargar consultas DBA</a></div><div class="table-scroll"><table><thead><tr><th>Control</th><th>Observación / criterio</th><th>Evidencia</th><th>Prueba</th><th>Estado actual</th></tr></thead><tbody>${REQUIRED_CONTROL_MATRIX.map(m=>{const c=CONTROLS.find(x=>x.id===m.id),test=AUDIT_TESTS.find(t=>t.id===m.test.split(/[ ·–]/)[0])||AUDIT_TESTS.find(t=>m.test.includes(t.id));return `<tr><td><strong>${esc(m.id)}</strong> ${esc(c?.title||'')}</td><td>${esc(c?.implementation||'')}</td><td>${esc(m.evidence)}</td><td>${esc(m.test)}</td><td>${esc(m.status)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function auditBatteryTable(){return `<section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>Batería de pruebas de auditoría</h2><small>Procedimiento, resultado esperado, herramienta y estado documentado.</small></div><a href="sql/08_auditor_controls.sql" download>Descargar verificación DBA de solo lectura</a></div><div class="table-scroll"><table><thead><tr><th>ID / tipo</th><th>Procedimiento</th><th>Resultado esperado</th><th>Herramienta</th><th>Resultado observado / pendiente</th></tr></thead><tbody>${AUDIT_TESTS.map(t=>`<tr><td><strong>${esc(t.id)}</strong><br>${esc(t.type)}</td><td>${esc(t.procedure)}</td><td>${esc(t.expected)}</td><td>${esc(t.tool)}</td><td>${esc(t.observed)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">“Según salida aportada” identifica una transcripción compartida en esta conversación, no una certificación independiente. Guardá el spool original y anexa fecha, cuenta, PDB y responsable.</p></section>`}
function controls(){const data=filteredControls(),linked=new Set(risks.flatMap(r=>selectedControls(r).map(c=>c.id))).size,known=isDemo()||Boolean(token),required=REQUIRED_CONTROL_MATRIX.length;return title('Controles orientados al riesgo','Del requisito elegido a la implementación y su prueba en Oracle.')+`<section class="control-intro"><div><span class="section-tag">ISO/IEC 27001 · 27002:2022</span><h2>Seleccionar. Aplicar. Comprobar.</h2><p>La matriz reúne los 15 controles que exige la asignación, más controles complementarios. Las correspondencias 2013 son orientativas; la aplicabilidad final depende del análisis del SGSI.</p><a href="#phva">Ver recomendaciones PHVA y ejecutar pruebas locales →</a></div><div class="control-intro-stats"><div><strong>${required}</strong><span>controles requeridos</span></div><div><strong>${CONTROLS.length-required}</strong><span>complementarios</span></div><div><strong>${known?linked:'—'}</strong><span>vinculados a riesgos registrados</span></div></div></section><div class="notice section-gap">ISO/IEC 27001 fija requisitos del SGSI; ISO/IEC 27002 orienta controles. Esta selección parcial no es una Declaración de Aplicabilidad ni certifica cumplimiento.</div><section class="control-catalog"><div class="catalog-heading"><div><h2>Catálogo aplicado a R-CONF</h2><p id="control-results-count">${data.length} de ${CONTROLS.length} controles visibles</p></div><span class="pill">Filtrá por riesgo para ver su tratamiento</span></div><div class="control-toolbar"><input id="control-search" aria-label="Buscar controles" placeholder="Buscar control, medida o evidencia…" value="${esc(controlFilter)}"><select id="control-kind" aria-label="Filtrar categoría"><option value="">Todas las categorías</option>${['Organizacional','Tecnológico'].map(x=>`<option value="${x}" ${controlKindFilter===x?'selected':''}>${x}</option>`).join('')}</select><select id="control-risk" aria-label="Filtrar por riesgo"><option value="">Todos los riesgos</option>${risks.map(r=>`<option value="${r.id}" ${controlRiskFilter===String(r.id)?'selected':''}>${code(r)} · ${esc(r.title)}</option>`).join('')}</select></div><div class="control-grid" id="control-grid">${controlCards(data)}</div></section>${controlMaturity()}${dbaTaskTable()}${auditorControlsTable()}${auditBatteryTable()}<section class="panel section-gap"><h2>Criterio de revisión</h2><div class="control-review-steps"><div><b>01</b><strong>Justificar</strong><p>Relacionar el control con un riesgo y documentar por qué aplica.</p></div><div><b>02</b><strong>Implementar</strong><p>Configurar el cambio con cuenta autorizada y conservar versión y responsable.</p></div><div><b>03</b><strong>Verificar</strong><p>Contrastar lo esperado con pruebas positivas y negativas, y revisar el residual.</p></div></div></section>`}
function refreshControlGrid(){const grid=$('#control-grid');if(!grid)return;const data=filteredControls();grid.innerHTML=controlCards(data);$('#control-results-count').textContent=`${data.length} de ${CONTROLS.length} controles visibles`;bindRows()}
function privileges(){return title('El permiso justo para cada función','Separar responsabilidades reduce la superficie de exposición.')+`<div class="split"><section class="panel"><h2>Tres fronteras de acceso</h2><ol class="steps"><li><strong>Persona:</strong> analista registra; auditor consulta; gestor aprueba decisiones residuales.</li><li><strong>Aplicación:</strong> RCONF_APP ejecuta un paquete y consulta vistas del proyecto. No recibe DBA ni SELECT ANY TABLE.</li><li><strong>Administración:</strong> el dueño instala los objetos. El DBA aplica y verifica las políticas de auditoría por separado.</li></ol><div class="helper">Los tokens de esta versión representan roles compartidos de laboratorio. Para producción se requieren identidades individuales, MFA y trazabilidad personal mediante Microsoft Entra ID.</div></section><section class="panel"><h2>Ruta de una operación</h2><div class="flow"><span>Usuario autorizado</span>→<span>API valida rol y campos</span>→<span>Paquete Oracle</span>→<span>Registro + evento</span></div><pre>GRANT CREATE SESSION TO rconf_app;
GRANT EXECUTE ON rconf_owner.risk_api
  TO rconf_runtime;
GRANT SELECT ON rconf_owner.risk_view
  TO rconf_runtime;</pre><p class="subtle">El servidor usa variables de entorno. Las contraseñas de Oracle no se ingresan en el sitio.</p></section></div><section class="panel table-panel"><div class="panel-heading"><h2>Matriz de autorización</h2></div><div class="table-scroll"><table><thead><tr><th>Operación</th><th>Analista web</th><th>Auditor web</th><th>Gestor web</th><th>RCONF_APP en Oracle</th></tr></thead><tbody>${[['Consultar riesgos','Sí','Sí','Sí','SELECT en vista'],['Registrar y actualizar','Sí','No','Sí','EXECUTE en paquete'],['Aprobar residual','No','No','Sí','API valida rol'],['Consultar bitácora','Sí','Sí','Sí','SELECT en vista'],['Leer tabla sensible base','No','No','No','Denegado'],['Crear usuarios / conceder DBA','No','No','No','Denegado']].map(row=>'<tr>'+row.map(t=>`<td>${t}</td>`).join('')+'</tr>').join('')}</tbody></table></div></section><div class="notice section-gap">La segmentación web se aplica en el servidor. La cuenta técnica compartida confía en esa API; una separación de alto aseguramiento requiere cuentas o contextos de base de datos por identidad y autenticación federada.</div>`}
function caseTestCards(){return CASE_TESTS.map(t=>`<article class="assurance-card ${t.tone}"><div class="assurance-top"><span class="test-id">${esc(t.id)}</span><span class="test-state">${esc(t.status)}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.observed)}</p><div class="assurance-meta"><span>Controles ${esc(t.controls)}</span><span>${esc(t.proof)}</span></div></article>`).join('')}
function caseStudy(){const live=risks.length,referenced=risks.filter(r=>r.evidence).length;const riskSummary=isDemo()||token?live+' riesgo'+(live===1?'':'s')+' registrado'+(live===1?'':'s')+' en '+(isDemo()?'la demostración':'Oracle')+'; '+referenced+' con referencia de evidencia.':'Conectá una sesión para consultar riesgos y referencias de Oracle.';return title('Caso de estudio: Faro Servicios S.A.','Una organización ficticia para explicar el riesgo; pruebas reales del laboratorio registradas por separado.')+`<section class="case-lead"><div><span class="brief-kicker">Encargo de aseguramiento · confidencialidad</span><h2>¿Puede una cuenta de aplicación leer información que no necesita?</h2><p>El caso examina un servicio de clientes que usa Oracle 21c XE. La amenaza es el acceso excesivo a datos personales; la respuesta combina vistas limitadas, un paquete de operaciones, roles mínimos y auditoría.</p></div><div class="case-scope"><span>Entorno observado</span><strong>Oracle XE 21c</strong><span>Contenedor</span><strong>XEPDB1</strong><span>Alcance</span><strong>Datos sintéticos</strong></div></section><div class="split section-gap"><section class="panel before-panel"><span class="section-tag">Escenario inicial · hipótesis</span><h2>Antes del control</h2><p class="copy">Se plantea una cuenta de aplicación con lectura directa de una tabla sensible. Este punto es un escenario de riesgo para la empresa ficticia, no una medición histórica de esta PDB.</p><ul class="info-list"><li>El exceso de permisos ampliaría la exposición ante una credencial comprometida.</li><li>Una vista sin bloqueo de la tabla base no reduciría el alcance efectivo.</li><li>Sin rastro revisable sería difícil reconstruir una lectura indebida.</li></ul></section><section class="panel after-panel"><span class="section-tag">Estado actual · salida aportada</span><h2>Después de aplicar el laboratorio</h2><p class="copy">RCONF_APP pudo consultar la vista enmascarada y RISK_VIEW. Las consultas directas a DEMO_PERSONAL y RISKS devolvieron ORA-00942. La política de auditoría aparece habilitada.</p><ul class="info-list"><li>Los permisos de lectura se concentran en vistas.</li><li>La escritura pasa por RISK_API y queda en la bitácora del proyecto.</li><li>Un evento de auditoría sobre DEMO_PERSONAL aún requiere correlación.</li></ul></section></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Registro de observaciones</h2><small>Transcripción de salidas compartidas el 26 de octubre de 2026; revisión independiente pendiente.</small></div><a href="#evidence">Ver expediente completo</a></div><div class="assurance-grid">${caseTestCards()}</div></section><div class="split section-gap"><section class="panel"><h2>Riesgos del caso en el sistema</h2><p class="copy">${riskSummary} La referencia debe vincularse con el archivo o acta original.</p><a href="#risks" class="text-link">Revisar registro de riesgos</a></section><section class="panel"><h2>Recomendaciones por prioridad</h2><ol class="recommendations">${AUDIT_NEXT.map(x=>`<li><span>${esc(x.priority)}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div></li>`).join('')}</ol></section></div><div class="notice section-gap">Faro Servicios S.A. es ficticia. Este laboratorio documenta controles y resultados puntuales; no representa una auditoría certificada de una empresa real.</div>`}
function caseStudyExpanded(){const focus=[...risks].sort((a,b)=>score(b)-score(a))[0],advice=focus?riskAdvice(focus,selectedControls(focus)):null;return caseStudy()+`<section class="panel section-gap"><div class="panel-heading"><div><span class="section-tag">Modelo de amenaza</span><h2>Qué debe responder la revisión</h2><small>Alcance del caso ficticio; los resultados observados se documentan por separado.</small></div></div><div class="case-threat-grid"><div><span>Activo</span><strong>Datos personales sintéticos</strong><p>La tabla base representa información que no debería quedar expuesta a la cuenta de aplicación.</p></div><div><span>Vía de entrada</span><strong>Credencial técnica</strong><p>Una credencial compartida o filtrada podría ampliar el acceso si recibe permisos directos o privilegios generales.</p></div><div><span>Impacto</span><strong>Lectura no autorizada</strong><p>La confidencialidad se compromete cuando una cuenta ve más campos o registros de los necesarios.</p></div><div><span>Criterio</span><strong>Necesidad de conocer</strong><p>La función permitida debe trabajar con vistas y paquete, mientras las tablas base permanecen inaccesibles.</p></div></div></section><section class="panel section-gap"><h2>Ruta de control y prueba</h2><div class="case-route"><div><b>01</b><strong>Identificar</strong><p>Cuenta, activo, función necesaria y exposición inherente.</p></div><div><b>02</b><strong>Restringir</strong><p>Conceder solo vistas y operaciones de paquete a RCONF_APP.</p></div><div><b>03</b><strong>Contrastar</strong><p>Ejecutar lectura permitida y denegada en la misma PDB.</p></div><div><b>04</b><strong>Decidir</strong><p>Relacionar evidencia, revisar auditoría y justificar residual.</p></div></div></section><div class="split section-gap"><section class="panel"><h2>Riesgo prioritario del registro</h2>${focus?`<span class="risk-code">${code(focus)}</span><h3>${esc(focus.title)}</h3><p class="copy">${esc(focus.asset)} · ${esc(focus.phase)} · exposición ${score(focus)} / 25.</p><div class="risk-card-advice"><span>Próximo paso recomendado</span><p>${esc(advice.action)}</p></div><button class="inline-button" data-edit="${focus.id}">Abrir riesgo registrado</button>`:`<p class="copy">${!isDemo()&&!token?'Conectá una sesión para ver el riesgo real y su recomendación PHVA.':'Todavía no hay riesgos registrados.'}</p>`}</section><section class="panel"><h2>Decisiones pendientes</h2><ol class="steps"><li>Correlacionar la fila de auditoría T11 con sentencia, sesión y hora.</li><li>Revisar EV-001 contra el archivo original y dejar constancia del revisor.</li><li>Comprobar el bloqueo de RCONF_OWNER al terminar la instalación.</li><li>Repetir las pruebas después de cada cambio y revisar el residual con el gestor.</li></ol></section></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Demostración defendible</h2><small>Un recorrido corto que separa hipótesis, configuración y resultado.</small></div></div><div class="case-demo-links"><a href="#risks"><strong>1 · Riesgo</strong><span>Abrir el registro y explicar el tratamiento elegido.</span></a><a href="#phva"><strong>2 · PHVA y pruebas</strong><span>Mostrar recomendaciones y ejecutar la comprobación local.</span></a><a href="#evidence"><strong>3 · Evidencia</strong><span>Contrastar T07/T08 y explicar por qué T11 sigue abierto.</span></a><a href="/documents/08_guion_demostracion.pdf" target="_blank" rel="noopener"><strong>Guion PDF ↗</strong><span>Orden, tiempos y comandos para la presentación.</span></a></div></section>`}
function comparison(){const groups=[['Organizacionales',37],['Personas',8],['Físicos',14],['Tecnológicos',34]];const rows=[['Gobierno del SGSI','27001: cláusulas 4–10 y Anexo A con 114 controles.','27001: mantiene el enfoque basado en riesgos, incorpora 4.2(c), precisa 4.4 e introduce 6.3 para planificar cambios. Anexo A: 93 controles.','Revisar procesos, partes interesadas y cambios del laboratorio.'],['Guía de controles','27002: 114 controles en 14 dominios.','27002: 93 controles en 4 grupos; cada control tiene propósito y cinco atributos para crear vistas.','Filtrar controles por riesgo R-CONF y documentar su aplicabilidad.'],['Acceso mínimo','Familia A.9 de control de acceso.','5.15–5.18, 8.2 y 8.3 reorganizan y actualizan la guía. El principio ya existía en 2013.','RCONF_APP usa vistas y paquete; tablas base denegadas.'],['Evidencia y monitoreo','A.12.4 cubría el registro de eventos.','8.15 mantiene registros; 8.16 explicita actividades de monitoreo.','Conservar salida de SQL y revisar excepciones del rastro.'],['Nube, configuración y datos','Se trataban mediante controles generales y proveedores.','5.23, 8.9, 8.11 y 8.12 dan referencias explícitas para nube, configuración, enmascaramiento y fuga.','Planificar canal Azure y proteger exportaciones; la vista limitada no es Oracle Data Redaction.']];const mappings=CONTROLS.map(c=>`<tr><td><span class="test-id">${esc(c.id)}</span> ${esc(c.title)}</td><td>${esc(c.old)}</td><td>${esc(c.risk)}</td><td>${esc(c.evidence)}</td></tr>`).join('');return title('ISO/IEC 27001 y 27002: 2013 → 2022','Una lectura comparativa orientada a decisiones de auditoría sobre confidencialidad en Oracle.')+`<section class="comparison-hero"><div><span class="section-tag">ISO/IEC 27002 · catálogo de controles</span><div class="comparison-big"><div><span>2013</span><strong>114</strong><small>14 dominios</small></div><span class="comparison-arrow">→</span><div><span>2022</span><strong>93</strong><small>4 grupos</small></div></div><p>La diferencia refleja fusiones, actualización de la guía y 11 controles nuevos. No mide por sí sola una reducción del trabajo de seguridad.</p></div><div class="comparison-notes"><strong>La distinción esencial</strong><p><b>27001</b> fija requisitos del SGSI y su tratamiento de riesgos. <b>27002</b> desarrolla orientación para seleccionar e implementar controles.</p><p>La matriz 5 × 5 de este sitio y el ciclo PHVA mostrado son decisiones del laboratorio, no fórmulas obligatorias de ISO.</p></div></section><section class="panel section-gap"><div class="panel-heading"><div><h2>Qué cambió para el auditor de bases de datos</h2><small>Requisitos, orientación y aplicación concreta en el laboratorio.</small></div></div><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Tema</th><th>2013</th><th>2022</th><th>Lectura para Oracle</th></tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(t=>`<td>${esc(t)}</td>`).join('')+'</tr>').join('')}</tbody></table></div></section><div class="split section-gap"><section class="panel"><h2>Cuatro grupos de 2022</h2><div class="group-bars">${groups.map(([name,n])=>`<div><div class="phase-label"><span>${name}</span><strong>${n} / 93</strong></div><progress max="93" value="${n}" aria-label="${name}"></progress></div>`).join('')}</div><p class="subtle">Los 93 controles se distribuyen en 37 organizacionales, 8 de personas, 14 físicos y 34 tecnológicos.</p></section><section class="panel"><h2>Cómo leer la correspondencia</h2><p class="copy">El Anexo B de ISO/IEC 27002:2022 permite rastrear relaciones entre ediciones. Una equivalencia puede combinar varios controles anteriores; esta tabla ofrece una selección orientativa para R-CONF.</p><p class="copy">La Declaración de Aplicabilidad completa requiere justificar inclusión, exclusión y estado de cada control pertinente al SGSI. Esta selección de 14 no la sustituye.</p></section></div><section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>Correspondencias seleccionadas para R-CONF</h2><small>14 controles del laboratorio; títulos y evidencia resumidos.</small></div></div><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Control 2022</th><th>Vínculo 2013 orientativo</th><th>Riesgos</th><th>Evidencia esperada</th></tr></thead><tbody>${mappings}</tbody></table></div></section><section class="panel section-gap"><h2>Los 11 controles nuevos de 2022</h2><div class="new-controls">${[['5.7','Inteligencia de amenazas'],['5.23','Servicios de nube'],['5.30','Preparación TIC para continuidad'],['7.4','Monitoreo de seguridad física'],['8.9','Gestión de configuración'],['8.10','Eliminación de información'],['8.11','Enmascaramiento de datos'],['8.12','Prevención de fuga de datos'],['8.16','Actividades de monitoreo'],['8.23','Filtrado web'],['8.28','Codificación segura']].map(([id,label])=>`<div><span class="test-id">${id}</span><span>${label}</span></div>`).join('')}</div><p class="subtle">Denominaciones resumidas en español. “Nuevo” se refiere al control explícito en el catálogo de 2022; algunos asuntos ya podían abordarse mediante controles generales de 2013.</p></section><div class="source-strip"><span>Fuentes técnicas</span><a href="https://committee.iso.org/files/live/sites/jtc1sc27/files/resources/ISO-IEC%20JTC%201-SC%2027_N22755_SC27%20Journal%20Vol%202%20Issue%202%20(update%20Dec%202022).pdf" target="_blank" rel="noreferrer">ISO/IEC SC 27 · editores de 27002</a><a href="https://blog.ansi.org/anab/iso-iec-27001-2013-2022-comparison/" target="_blank" rel="noreferrer">ANAB · comparación 27001</a></div>`}
function evidence(){const records=isDemo()||token?risks.filter(r=>r.evidence).length:null;return title('Expediente de evidencias','Qué se probó, qué respondió Oracle y qué debe revisar el responsable.',`<div class="button-row"><button class="secondary" id="print">Imprimir expediente</button><button class="secondary" id="export">Exportar registro JSON</button></div>`)+modeNotice()+`<section class="evidence-summary"><div><span>Pruebas con salida aportada</span><strong>03</strong><small>T07, T08 y T11 · 26 oct 2026</small></div><div><span>Resultados conformes</span><strong>02</strong><small>Lecturas limitadas y denegaciones</small></div><div><span>Revisión pendiente</span><strong>01</strong><small>Correlación del rastro de auditoría</small></div><div><span>Riesgos con referencia</span><strong>${records===null?'—':records.toString().padStart(2,'0')}</strong><small>${isDemo()?'Datos ilustrativos':token?'Registro actual de Oracle':'Conectá sesión para consultar'}</small></div></section><section class="panel section-gap"><div class="panel-heading"><div><h2>Pruebas ejecutadas en Oracle</h2><small>Resultados transcritos de las salidas compartidas por el estudiante; revisión independiente pendiente.</small></div></div><div class="assurance-grid">${CASE_TESTS.map(t=>`<article class="assurance-card ${t.tone}"><div class="assurance-top"><span class="test-id">${esc(t.id)}</span><span class="test-state">${esc(t.status)}</span></div><h3>${esc(t.title)}</h3><dl><dt>Esperado</dt><dd>${esc(t.expected)}</dd><dt>Observado</dt><dd>${esc(t.observed)}</dd><dt>Fuente</dt><dd>${esc(t.proof)}</dd></dl><div class="assurance-meta"><span>Controles ${esc(t.controls)}</span><span>${esc(t.phase)}</span></div></article>`).join('')}</div></section><div class="split section-gap"><section class="panel"><h2>Cadena de evidencia mínima</h2><ol class="steps"><li>Identificar prueba, riesgo, control, ejecutor y revisor.</li><li>Conservar fecha, PDB, cuenta, sentencia, resultado esperado y salida observada.</li><li>Guardar el archivo original en una ubicación restringida y referenciarlo aquí.</li><li>Correlacionar la bitácora de la aplicación con la auditoría SQL cuando corresponda.</li></ol></section><section class="panel"><h2>Lectura crítica del rastro</h2><p class="copy">La consulta DBA mostró <code>RCONF_ACCESS_POLICY</code> habilitada. Aparecieron eventos de SELECT con código 0 para MASKED_PERSONAL y RISK_VIEW, y dos filas para DEMO_PERSONAL con códigos 2004 y 0. La denegación observada en SQL*Plus fue ORA-00942.</p><p class="copy">Antes de cerrar T11 como conforme, conviene identificar qué sentencia y sesión generó la fila de código 0. El sitio no consulta <code>UNIFIED_AUDIT_TRAIL</code> con RCONF_APP.</p></section></div><section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>Referencias vinculadas a riesgos</h2><small>La presencia de una referencia no valida su contenido.</small></div></div><div class="table-scroll"><table><thead><tr><th>Riesgo</th><th>Referencia</th><th>Fase</th><th>Decisión residual</th></tr></thead><tbody>${risks.map(r=>`<tr><td><button class="inline-button" data-edit="${r.id}">${code(r)}</button></td><td>${esc(r.evidence||'Pendiente')}</td><td>${esc(r.phase)}</td><td>${esc(r.decision||'Pendiente')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">'+(!isDemo()&&!token?'Conectá una sesión para consultar riesgos.':'Todavía no hay riesgos registrados.')+'</td></tr>'}</tbody></table></div></section><section class="panel table-panel section-gap"><div class="panel-heading"><div><h2>Bitácora de cambios del sistema</h2><small>${isDemo()?'Acciones de esta demostración':'Últimos 200 eventos del proyecto Oracle'}</small></div></div><div class="table-scroll"><table><thead><tr><th>Fecha UTC</th><th>Riesgo</th><th>Actor</th><th>Acción</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(e.at)}</td><td>R-CONF-${String(e.risk_id).padStart(2,'0')}</td><td>${esc(e.actor)}</td><td>${esc(e.action)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">'+(!isDemo()&&!token?'Conectá una sesión para consultar la bitácora.':'Todavía no se han registrado cambios.')+'</td></tr>'}</tbody></table></div></section><div class="helper">La bitácora transaccional registra cambios de riesgos. La auditoría de lecturas SQL se verifica por separado con la cuenta DBA mediante 04_verify_dba.sql.</div>`}
function resources(){const files=[['Informe académico','01_informe_academico.pdf'],['Manual técnico Oracle','02_manual_tecnico.pdf'],['Plan de Azure','03_azure.pdf'],['Declaración de uso de IA','04_uso_ia.pdf'],['Expediente de pruebas Oracle','07_evidencia_oracle_2026-10-26.pdf'],['Guion de presentación','08_guion_demostracion.pdf'],['Guía de pruebas y comparación con el video','10_pruebas_y_video.pdf']];return title('Documentación y fuentes','Un proyecto reproducible, con decisiones y límites explícitos.')+aiDisclosurePanel()+`<div class="split"><section class="panel"><h2>Ficha académica</h2><p class="copy"><strong>Efrain Retana Segura</strong><br>Universidad Nacional<br>Facultad de Ciencias Exactas y Naturales<br>Escuela de Informática<br>EIF402 · Administración de Bases de Datos<br>II Ciclo 2026 · Docente: Johnny Villalobos Murillo</p><h3>Objetivo del proyecto</h3><p class="copy">Proponer e implementar un laboratorio de controles para mitigar riesgos de confidencialidad en Oracle, usando ISO/IEC 27001:2022 e ISO/IEC 27002:2022, PHVA y mínimo privilegio, y verificar su eficacia mediante pruebas documentadas.</p><h3>Uso de IA generativa</h3><p class="copy">Este prototipo y sus documentos se elaboraron con asistencia de Codex. La validación local, adaptación y defensa corresponden al estudiante y deben registrarse cuando se realicen. La asignación específica permite IA con declaración y validación; el registro documenta los aportes y las comprobaciones del estudiante.</p></section><section class="panel"><h2>Cómo ponerlo en marcha</h2><ol class="steps"><li>Ejecutar <code>start-local.ps1</code> y explorar la demostración.</li><li>Revisar <code>docs/02_manual_tecnico.md</code> e instalar los scripts SQL en una PDB de laboratorio.</li><li>Configurar <code>.env</code> con la cuenta limitada y tres tokens distintos.</li><li>Ejecutar las pruebas positivas y negativas. Conservar evidencia restringida.</li><li>Seguir <code>docs/03_azure.md</code> para Azure App Service y conexión híbrida.</li></ol><p class="subtle">Los documentos editables y PDF están incluidos en el paquete del proyecto y en el repositorio privado.</p><div class="button-row"><button class="secondary" id="print">Imprimir esta vista</button>${isDemo()?'<button class="secondary" id="reset">Restablecer demostración</button>':''}</div></section></div><section class="panel section-gap"><h2>Documentos para revisar y presentar</h2><p class="subtle">Archivos PDF del proyecto. El guion explica el orden de la exposición y las pruebas en vivo.</p>${files.map(([label,file])=>`<a class="resource" href="/documents/${file}" target="_blank" rel="noopener"><strong>${esc(label)} ↗</strong><small>${esc(file)}</small></a>`).join('')}</section><section class="panel section-gap"><h2>Fuentes consultadas</h2><p class="subtle">Consulta: 25 y 26 de octubre de 2026. Las normas completas están sujetas a licencia.</p>${SOURCES.map(([name,desc,url])=>`<a class="resource" href="${url}" target="_blank" rel="noreferrer"><strong>${esc(name)} ↗</strong><small>${esc(desc)}</small></a>`).join('')}</section>`}
function render(){activePage=location.hash.slice(1)||'overview';if(!labels[activePage])activePage='overview';$('#breadcrumb').textContent=labels[activePage];document.title=labels[activePage]+' · R-CONF';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===activePage);if(a.dataset.page===activePage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#connection').textContent=isDemo()?'● Modo demostración':role?'● Oracle · '+role:'○ Oracle · sin sesión';$('#connect').textContent=isDemo()?'Sobre la conexión':token?'Cerrar sesión':'Conectar sesión';$('#content').innerHTML=({audit:auditPage,database:databaseLab,overview,case:caseWorkspace,risks:registry,phva,controls,privileges,comparison,evidence,resources}[activePage])();bind()}
function bind(){bindDatabaseLab();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(Number(b.dataset.edit)));if($('#new-risk'))$('#new-risk').onclick=()=>edit();if($('#export'))$('#export').onclick=exportData;if($('#search'))$('#search').oninput=e=>{filter=e.target.value;$('#registry-table').innerHTML=filteredTable();bindRows()};if($('#status-filter'))$('#status-filter').onchange=e=>{statusFilter=e.target.value;$('#registry-table').innerHTML=filteredTable();bindRows()};if($('#control-search'))$('#control-search').oninput=e=>{controlFilter=e.target.value;refreshControlGrid()};if($('#control-kind'))$('#control-kind').onchange=e=>{controlKindFilter=e.target.value;refreshControlGrid()};if($('#control-risk'))$('#control-risk').onchange=e=>{controlRiskFilter=e.target.value;refreshControlGrid()};if($('#print'))$('#print').onclick=()=>window.print();if($('#reset'))$('#reset').onclick=()=>{if(confirm('¿Restablecer los datos de demostración? Se borrarán los cambios de este navegador.')){localStorage.removeItem(STORE_KEY);loadDemo();render();toast('Demostración restablecida.')}}}
function bindRows(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(Number(b.dataset.edit)))}
document.addEventListener('click',async event=>{const run=event.target.closest('#run-runtime-check');if(run){run.disabled=true;run.textContent='Comprobando Oracle…';checkError='';try{checkResults=await api('/api/checks/runtime',{method:'POST'});}catch(err){checkResults=null;checkError=err.message}render();return}if(event.target.closest('#download-check')&&checkResults){const payload={project:'R-CONF',type:'comprobacion_local',...checkResults,notice:'Resultado técnico temporal. Requiere salida original y revisión antes de considerarse evidencia.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='rconf-comprobacion-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}});
function exportData(){const data={project:'R-CONF',mode,exported_at:new Date().toISOString(),notice:isDemo()?'DATOS SINTÉTICOS. No acreditan verificaciones en Oracle.':'Registro del proyecto; revisar clasificación antes de compartir.',risks,events};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='rconf-'+mode+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function ensureControlPicker(){const form=$('#risk-form');const current=form.elements.controls;if(current&&current.tagName==='INPUT'){const select=document.createElement('select');select.name='controls';select.multiple=true;select.size=5;select.required=true;select.setAttribute('aria-describedby','controls-help');current.replaceWith(select);const help=document.createElement('small');help.id='controls-help';help.textContent='Seleccioná uno o varios controles; usá Ctrl/Cmd para marcar más de uno.';select.parentElement.appendChild(help);return select}return current}
function edit(id){const form=$('#risk-form');const picker=ensureControlPicker();form.reset();$('#form-error').textContent='';const r=id?risks.find(x=>x.id===id):{id:'',version:'',probability:3,impact:3,residual_probability:3,residual_impact:3,phase:'Planificar',status:'Abierto',due:new Date().toISOString().slice(0,10),controls:''};for(const [key,value]of Object.entries(r)){if(form.elements[key]&&key!=='controls')form.elements[key].value=value}const selected=new Set(String(r.controls||'').split(',').map(x=>x.trim()).filter(Boolean));Array.from(picker.options).forEach(option=>{option.selected=selected.has(option.value)});$('#dialog-heading').textContent=id?code(r):'Nuevo riesgo';Array.from(form.elements).forEach(e=>{if(!['button','submit','hidden'].includes(e.type))e.disabled=!canWrite()});form.querySelector('[type=submit]').hidden=!canWrite();$('#risk-dialog').showModal()}
function check(data,old){if(!data.title.trim()||!data.asset.trim()||!data.owner.trim()||!data.controls.trim()||!data.treatment.trim())throw Error('Completá todos los campos obligatorios.');if(!old&&(data.phase!=='Planificar'||data.status!=='Abierto'))throw Error('Un riesgo nuevo inicia Abierto en Planificar.');if(old&&PHASES.indexOf(data.phase)>PHASES.indexOf(old.phase)+1)throw Error('Avanzá una fase PHVA a la vez.');if(data.phase!=='Planificar'&&!data.evidence.trim())throw Error('Agregá una referencia de evidencia antes de avanzar.');if(['Mitigado','Aceptado'].includes(data.status)){if(!isDemo()&&role!=='gestor')throw Error('Solo el gestor puede aprobar el residual.');if(data.phase!=='Actuar'||!data.decision.trim()||!data.evidence.trim())throw Error('La decisión requiere Actuar, evidencia y justificación.');if(data.status==='Mitigado'&&residual(data)>4)throw Error('Residual superior a 4: continuá el tratamiento o aceptalo con justificación.')}}
$('#risk-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.controls=Array.from(e.target.elements.controls.selectedOptions).map(option=>option.value).join(', ');const id=Number(data.id)||null;for(const k of ['probability','impact','residual_probability','residual_impact','version'])data[k]=Number(data[k]);try{check(data,id?risks.find(r=>r.id===id):null);if(isDemo()){data.id=id||Math.max(0,...risks.map(r=>r.id))+1;data.version=(data.version||0)+1;risks=id?risks.map(r=>r.id===id?data:r):[...risks,data];events.unshift({id:events.length+1,risk_id:data.id,actor:'Demostración',action:id?'Actualización':'Creación',at:new Date().toISOString()});saveDemo()}else{delete data.id;await api('/api/risks'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(data)});await refresh()}$('#risk-dialog').close();render();toast('Riesgo guardado'+(isDemo()?' en este navegador.':'.'))}catch(err){$('#form-error').textContent=err.message}};
for(const k of ['probability','impact','residual_probability','residual_impact'])$('#risk-form').elements[k].innerHTML=[1,2,3,4,5].map(i=>`<option value="${i}">${i} · ${['Muy bajo','Bajo','Medio','Alto','Muy alto'][i-1]}</option>`).join('');
for(const [key,values]of [['phase',PHASES],['status',STATUSES]])$('#risk-form').elements[key].innerHTML=values.map(v=>`<option>${v}</option>`).join('');
ensureControlPicker().innerHTML=CONTROLS.map(c=>`<option value="${esc(c.id)}">${esc(c.id)} · ${esc(c.title)}</option>`).join('');
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#risk-dialog').close();
$('#cancel-session').onclick=()=>{$('#token').value='';$('#session-dialog').close()};
$('#connect').onclick=()=>{if(isDemo()){location.hash='resources';toast('Para conectar Oracle, configurá APP_MODE=oracle y reiniciá el servidor.')}else if(token){token='';role=null;refresh()}else{$('#session-error').textContent='';$('#session-dialog').showModal()}};
$('#session-form').onsubmit=async e=>{e.preventDefault();token=$('#token').value;$('#token').value='';try{role=(await api('/api/session')).role;$('#session-dialog').close();await refresh()}catch(err){token='';role=null;$('#session-error').textContent=err.message}};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
async function init(){try{mode=(await api('/api/config')).mode;await refresh()}catch{$('#content').innerHTML='<h1>No se pudo cargar el laboratorio</h1><p>Verificá que el servidor esté activo y recargá la página.</p>'}}init();
